:root {
  --bg: #1b1d2a;
  --card: #262a3d;
  --accent: #5eead4;
  --accent-dark: #2dd4bf;
  --text: #e2e8f0;
  --muted: #94a3b8;
  --danger: #fb7185;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(circle at 50% 0%, #2b2f45, var(--bg));
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  padding: 16px;
}

.card {
  width: 100%;
  max-width: 460px;
  background: var(--card);
  border-radius: 16px;
  padding: 20px;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
}

.title {
  margin: 0;
  font-size: 1.5rem;
  letter-spacing: 0.5px;
  color: var(--accent);
}

.score {
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--muted);
}

.score span {
  color: var(--accent);
}

.board-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
}

canvas {
  width: 100%;
  height: 100%;
  display: block;
  background: #14161f;
  border-radius: 10px;
  image-rendering: pixelated;
  border: 2px solid #333850;
}

.overlay {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 12px;
  padding: 20px;
  background: rgba(20, 22, 31, 0.92);
  border-radius: 10px;
  transition: opacity 0.2s ease;
}

.overlay.hidden {
  display: none;
}

.overlay h2 {
  margin: 0;
  font-size: 1.4rem;
  color: var(--accent);
}

.overlay p {
  margin: 0;
  color: var(--muted);
  line-height: 1.5;
  font-size: 1rem;
}

.overlay .final-score {
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--text);
}

.controls {
  display: flex;
  gap: 12px;
}

.btn {
  flex: 1;
  font: inherit;
  font-weight: 600;
  padding: 12px 16px;
  border-radius: 10px;
  border: 2px solid #3a405c;
  background: #2f344a;
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s ease, transform 0.05s ease, border-color 0.15s ease;
}

.btn:hover {
  background: #3a405c;
  border-color: var(--accent-dark);
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:active {
  transform: translateY(2px);
  background: #262a3d;
}

.btn.primary {
  background: var(--accent-dark);
  border-color: var(--accent);
  color: #08201c;
}

.btn.primary:hover {
  background: var(--accent);
}

.btn.primary:active {
  background: var(--accent-dark);
}

.hint {
  margin: 0;
  text-align: center;
  font-size: 0.9rem;
  color: var(--muted);
}

@media (max-width: 400px) {
  .card {
    padding: 14px;
    gap: 12px;
  }
  .title {
    font-size: 1.25rem;
  }
  .btn {
    padding: 10px 12px;
  }
}

(function () {
  'use strict';

  const canvas = document.getElementById('board');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const overlay = document.getElementById('overlay');
  const overlayTitle = document.getElementById('overlay-title');
  const overlayText = document.getElementById('overlay-text');
  const overlayBtn = document.getElementById('overlay-btn');
  const pauseBtn = document.getElementById('pause-btn');
  const restartBtn = document.getElementById('restart-btn');

  const GRID = 20;
  const CELL = canvas.width / GRID;
  const TICK_MS = 140;

  const COLORS = {
    bg: '#14161f',
    grid: '#1c1f2c',
    snake: '#5eead4',
    head: '#2dd4bf',
    food: '#fb7185'
  };

  let snake, dir, nextDir, food, score, state, acc, lastTime;

  function reset() {
    snake = [{ x: 8, y: 10 }, { x: 7, y: 10 }, { x: 6, y: 10 }];
    dir = { x: 1, y: 0 };
    nextDir = { x: 1, y: 0 };
    score = 0;
    scoreEl.textContent = '0';
    placeFood();
    state = 'paused';
    acc = 0;
    lastTime = 0;
    updatePauseBtn();
    draw();
  }

  function placeFood() {
    let pos;
    do {
      pos = {
        x: Math.floor(Math.random() * GRID),
        y: Math.floor(Math.random() * GRID)
      };
    } while (snake.some(s => s.x === pos.x && s.y === pos.y));
    food = pos;
  }

  function updatePauseBtn() {
    pauseBtn.textContent = state === 'running' ? 'Pause' : 'Resume';
  }

  function startGame() {
    reset();
    state = 'running';
    updatePauseBtn();
    hideOverlay();
    lastTime = performance.now();
    requestAnimationFrame(loop);
  }

  function togglePause() {
    if (state === 'running') {
      state = 'paused';
      updatePauseBtn();
    } else if (state === 'paused') {
      state = 'running';
      updatePauseBtn();
      lastTime = performance.now();
      requestAnimationFrame(loop);
    }
  }

  function restart() {
    startGame();
  }

  function showOverlay(title, text, btnLabel) {
    overlayTitle.textContent = title;
    overlayText.innerHTML = text;
    overlayBtn.textContent = btnLabel;
    overlay.classList.remove('hidden');
    overlayBtn.focus();
  }

  function hideOverlay() {
    overlay.classList.add('hidden');
  }

  function gameOver() {
    state = 'over';
    updatePauseBtn();
    showOverlay(
      'Game Over',
      'Final score: <span class="final-score">' + score + '</span><br>Press Restart or the button below to play again.',
      'Play Again'
    );
  }

  function loop(time) {
    if (state !== 'running') return;
    const dt = time - lastTime;
    lastTime = time;
    acc += dt;
    if (acc >= TICK_MS) {
      acc -= TICK_MS;
      step();
    }
    draw();
    if (state === 'running') requestAnimationFrame(loop);
  }

  function step() {
    dir = nextDir;
    const head = { x: snake[0].x + dir.x, y: snake[0].y + dir.y };

    if (head.x < 0 || head.y < 0 || head.x >= GRID || head.y >= GRID) {
      gameOver();
      return;
    }
    if (snake.some(s => s.x === head.x && s.y === head.y)) {
      gameOver();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score += 10;
      scoreEl.textContent = String(score);
      placeFood();
    } else {
      snake.pop();
    }
  }

  function draw() {
    ctx.fillStyle = COLORS.bg;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.strokeStyle = COLORS.grid;
    ctx.lineWidth = 1;
    for (let i = 1; i < GRID; i++) {
      ctx.beginPath();
      ctx.moveTo(i * CELL, 0);
      ctx.lineTo(i * CELL, canvas.height);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, i * CELL);
      ctx.lineTo(canvas.width, i * CELL);
      ctx.stroke();
    }

    ctx.fillStyle = COLORS.food;
    ctx.fillRect(food.x * CELL + 1, food.y * CELL + 1, CELL - 2, CELL - 2);

    snake.forEach((seg, i) => {
      ctx.fillStyle = i === 0 ? COLORS.head : COLORS.snake;
      ctx.fillRect(seg.x * CELL + 1, seg.y * CELL + 1, CELL - 2, CELL - 2);
    });
  }

  function setDirection(x, y) {
    if (state !== 'running') return;
    if (dir.x === -x && dir.y === -y) return;
    if (dir.x === x && dir.y === y) return;
    nextDir = { x, y };
  }

  document.addEventListener('keydown', (e) => {
    switch (e.key) {
      case 'ArrowUp': e.preventDefault(); setDirection(0, -1); break;
      case 'ArrowDown': e.preventDefault(); setDirection(0, 1); break;
      case 'ArrowLeft': e.preventDefault(); setDirection(-1, 0); break;
      case 'ArrowRight': e.preventDefault(); setDirection(1, 0); break;
      case 'p': case 'P': e.preventDefault(); togglePause(); break;
      case 'r': case 'R': e.preventDefault(); restart(); break;
    }
  });

  pauseBtn.addEventListener('click', togglePause);
  restartBtn.addEventListener('click', restart);
  overlayBtn.addEventListener('click', () => {
    if (state === 'over') restart();
    else startGame();
  });

  reset();
  showOverlay(
    'How to Play',
    'Use the arrow keys to move the snake. Eat the food to grow and earn points. Press <strong>P</strong> or the Pause button to pause/resume. Press <strong>R</strong> or Restart to start over.',
    'Start Game'
  );
})();
